static const size_t CaseIgnRangesCount = 452;

static const uint32_t CaseFinalSigmaMap[] = { 0x03C2u };
static const size_t CaseFinalSigmaMapLen = 1;

static uint32_t CaseBsearchSimple(const CaseSimpleEntry *t,
                                        size_t n, uint32_t cp)
{
    size_t lo = 0, hi = n;
    while (lo < hi) {
        size_t mid = lo + (hi - lo) / 2u;
        if (cp < t[mid].cp) {
            hi = mid;
        } else if (cp > t[mid].cp) {
            lo = mid + 1u;
        } else {
            return t[mid].mapped;
        }
    }
    return cp;
}

static size_t CaseBsearchFull(const CaseFullIndex *idx, size_t n,
                                    const uint32_t *data, uint32_t cp,
                                    uint32_t *out, size_t outCap)
{
    size_t lo = 0, hi = n;
    while (lo < hi) {
        size_t mid = lo + (hi - lo) / 2u;
        if (cp < idx[mid].cp) {
            hi = mid;
        } else if (cp > idx[mid].cp) {
            lo = mid + 1u;
        } else {
            size_t len = idx[mid].length;
            size_t i;
            if (outCap < len) {
                return 0;
            }
            for (i = 0; i < len; i++) {
                out[i] = data[idx[mid].offset + i];
            }
            return len;
        }
    }
    if (outCap < 1u) {
        return 0;
    }
    out[0] = cp;
    return 1;
}

static int CaseBsearchBool(const CaseBoolRange *r, size_t n,
                                 uint32_t cp)
{
    size_t lo = 0, hi = n;
    while (lo < hi) {
        size_t mid = lo + (hi - lo) / 2u;
        if (cp < r[mid].start) {
            hi = mid;
        } else if (cp > r[mid].end) {
            lo = mid + 1u;
        } else {
            return 1;
        }
    }
    return 0;
}

uint32_t CaseSimpleUpper(uint32_t cp)
{
    return CaseBsearchSimple(CaseSu, CaseSuCount, cp);
}
uint32_t CaseSimpleLower(uint32_t cp)
{
    return CaseBsearchSimple(CaseSl, CaseSlCount, cp);
}
uint32_t CaseSimpleTitle(uint32_t cp)
{
    return CaseBsearchSimple(CaseSt, CaseStCount, cp);
}
uint32_t CaseSimpleFold(uint32_t cp)
{
    return CaseBsearchSimple(CaseSf, CaseSfCount, cp);
}

size_t CaseFullUpper(uint32_t cp, uint32_t *out, size_t outCap)
{
    return CaseBsearchFull(CaseFuIdx, CaseFuIdxCount,
                                  CaseFuData, cp, out, outCap);
}
size_t CaseFullLower(uint32_t cp, uint32_t *out, size_t outCap)
{
    return CaseBsearchFull(CaseFlIdx, CaseFlIdxCount,
                                  CaseFlData, cp, out, outCap);
}
size_t CaseFullTitle(uint32_t cp, uint32_t *out, size_t outCap)
{
    return CaseBsearchFull(CaseFtIdx, CaseFtIdxCount,
                                  CaseFtData, cp, out, outCap);
}
size_t CaseFullFold(uint32_t cp, uint32_t *out, size_t outCap)
{
    return CaseBsearchFull(CaseFfIdx, CaseFfIdxCount,
                                  CaseFfData, cp, out, outCap);
}

size_t CaseFinalSigmaLower(uint32_t *out, size_t outCap)
{
    size_t i;
    if (outCap < CaseFinalSigmaMapLen) {
        return 0;
    }
    for (i = 0; i < CaseFinalSigmaMapLen; i++) {
        out[i] = CaseFinalSigmaMap[i];
    }
    return CaseFinalSigmaMapLen;
}

int CaseIsCased(uint32_t cp)
{
    return CaseBsearchBool(CaseCasedRanges, CaseCasedRangesCount, cp);
}
int CaseIsCaseIgnorable(uint32_t cp)
{
    return CaseBsearchBool(CaseIgnRanges, CaseIgnRangesCount, cp);
}

